/// <summary>
/// MPJ_24808_PalletRounding
/// Pallet rounding logic for a sales line.
/// </summary>

class METPalletRounding
{
}

Method.Source:
    /// <summary>
    /// Performs pallet rounding.
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_custAccount">Customer account</param>
    /// <param name = "_siteId">Inventory site id</param>
    /// <param name = "_orderedQty">Ordered quantity</param>    
    /// <returns>New ordered quantity</returns>
    public InventQty applyPalletRounding(ItemId         _itemId, 
                                         CustAccount    _custAccount, 
                                         InventSiteId   _siteId, 
                                         InventQty      _orderedQty)
    {
        METInventItemOrderSetup         metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_itemId, _siteId);

        InventQty                       orderedQty  = _orderedQty;
        METPalletRoundingPercentage     roundingPercentage;

        if (metInventItemOrderSetup.RecId)
        {
            roundingPercentage  = this.findPalletRoundingPercentage(_itemId, _custAccount, _siteId);

            if (roundingPercentage > 0)
            {
                InventQty   modQty = _orderedQty mod metInventItemOrderSetup.PalletQty;

                if (((modQty * 100)/metInventItemOrderSetup.PalletQty) > roundingPercentage)
                {
                    orderedQty  += metInventItemOrderSetup.PalletQty - modQty;
                }
            }
        }

        return orderedQty;
    }

    /// <summary>
    /// Finds pallet rounding percentage.
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_custAccount">Customer account</param>
    /// <param name = "_siteId">Inventory site id</param>
    /// <returns>Pallet rounding percentage</returns>
    public METPalletRoundingPercentage  findPalletRoundingPercentage(ItemId         _itemId, 
                                                                     CustAccount    _custAccount, 
                                                                     InventSiteId   _siteId)
    {
        EcoResCategoryName      category    = this.findItemCategory(_itemId);
        METCustOperGroupId      custOperGroupId = CustTable::find(_custAccount).METCustOperGroupId;        

        METPalletRoundingPolicyHeader   policyHeader;
        METPalletRoundingPolicyLine     policyLine;
        METPalletRoundingPercentage     roundingPercentage;

        select firstonly RecId from policyLine
            // CB223_PalletRounding RuleType no longer required
            //where policyLine.RuleType == METPalletRoundingPolicyRuleType::Exclude
               // CB223_PalletRounding field moved to header
               //&& policyLine.InventSiteId       == _siteId              
               where policyLine.ItemCode           == METItemTableGroup::Table
               && policyLine.ItemRelation       == _itemId
               && ((policyLine.AccountCode        == METCustomerGroupAll::Table
                    && policyLine.AccountRelation    == _custAccount) ||
                    (policyLine.AccountCode        == METCustomerGroupAll::GroupId
                    && policyLine.AccountRelation    == custOperGroupId) ||
                    policyLine.AccountCode          == METCustomerGroupAll::All)
            exists join policyHeader
                // CB223_PalletRounding PolicyName replaced by new unique link InventSiteId
                   //where policyHeader.PolicyName == policyLine.PolicyName
                   where policyHeader.InventSiteId == policyLine.InventSiteId
                   && policyHeader.Active == NoYes::Yes;

        if (!policyLine.RecId)
        {
            select firstonly RecId from policyLine
                // CB223_PalletRounding RuleType no longer required
                //where policyLine.RuleType == METPalletRoundingPolicyRuleType::Include
                   // CB223_PalletRounding field moved to header
                   //&& policyLine.InventSiteId == _siteId
                   where ((policyLine.AccountCode          == METCustomerGroupAll::Table
                        && policyLine.AccountRelation   == _custAccount
                        && policyLine.ItemCode          == METItemTableGroup::Table
                        && policyLine.ItemRelation      == _itemId)
                       ||
                       (policyLine.AccountCode          == METCustomerGroupAll::Table
                        && policyLine.AccountRelation   == _custAccount
                        && policyLine.ItemCode          == METItemTableGroup::GroupId
                        && policyLine.ItemRelation      == category)
                       /*||
                       (policyLine.AccountCode          == METCustomerGroupAll::Table
                        && policyLine.AccountRelation   == _custAccount
                        && policyLine.ItemCode          == METItemTableGroup::All)*/
                       ||
                       (policyLine.AccountCode          == METCustomerGroupAll::GroupId
                        && policyLine.AccountRelation   == custOperGroupId
                        && policyLine.ItemCode          == METItemTableGroup::Table
                        && policyLine.ItemRelation      == _itemId)
                       ||
                       (policyLine.AccountCode          == METCustomerGroupAll::GroupId
                        && policyLine.AccountRelation   == custOperGroupId
                        && policyLine.ItemCode          == METItemTableGroup::GroupId
                        && policyLine.ItemRelation      == category)
                       ||
                       /*(policyLine.AccountCode          == METCustomerGroupAll::GroupId
                        && policyLine.AccountRelation   == custOperGroupId
                        && policyLine.ItemCode          == METItemTableGroup::All)
                       ||*/
                       (policyLine.AccountCode          == METCustomerGroupAll::All
                        && policyLine.ItemCode          == METItemTableGroup::Table
                        && policyLine.ItemRelation      == _itemId)
                       ||
                       (policyLine.AccountCode          == METCustomerGroupAll::All
                        && policyLine.ItemCode          == METItemTableGroup::GroupId
                        && policyLine.ItemRelation      == category)
                       /*||
                       (policyLine.AccountCode          == METCustomerGroupAll::All
                        && policyLine.ItemCode          == METItemTableGroup::All)*/)
                // CB223_PalletRounding field moved to line
                join /*RoundingPercentage,*/ RecId from policyHeader
                // CB223_PalletRounding PolicyName replaced by new unique link InventSiteId
                //where policyHeader.PolicyName       == policyLine.PolicyName
                where policyHeader.InventSiteId       == policyLine.InventSiteId
                       && policyHeader.Active           == NoYes::Yes;

            if (policyHeader.RecId)
            {
                // CB223_PalletRounding field moved to line
                //roundingPercentage  = policyHeader.RoundingPercentage;
            }
                   
        }

        return roundingPercentage;
    }

    /// <summary>
    /// Finds item category.
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>Item category</returns>
    public EcoResCategoryName findItemCategory(ItemId   _itemId)
    {
        InventTable             inventTable = InventTable::find(_itemId);
        EcoResCategory          category;               

        category    = EcoResProductCategory::findCategoryByProduct(inventTable.Product, 
                                                                   EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::Retail).CategoryHierarchy);

        while (category.RecId && category.Level > METConstants::CategoryLevel)
        {
            category    = EcoResCategory::find(category.ParentCategory);
        }

        return ((category.RecId && category.Level == METConstants::CategoryLevel) ? category.Name : '');
    }
